text:
{
  "units": [
    {
      "issue": "在显著虚构题设下，确定SP-01到账后A、B、C债务的可支持剩余分项及合计，并区分丁、戊、己的保证效力、责任存续与即时给付责任；核心联动为保证状态影响B/C之间的付款抵充。",
      "decisive_facts": [
        {
          "fact": "A于2022年成立，资金来源为套取的银行信贷资金；实际交付142987.00元，乙已返还20123.00元。乙不知资金来源及约定利率仅6%均为题设事实，不是已确定的效力结论。无效清算协议以A被认定无效为条件。",
          "spans": ["S01", "S02"]
        },
        {
          "fact": "B于2022-01-12实际交付并成立，票面196389.00元包含预扣利息12319.00元，实际本金184070.00元；约定年利率13.20%，题设成立时一年期LPR为3.70%。",
          "spans": ["S03"]
        },
        {
          "fact": "B在2022-07-06、2022-10-17、2023-01-09重新出具借据，各次新增交付均为零。双方约定结息但不更新债务，沿用原利率及原成立时LPR；按实际日数/365计算，中间不取分。",
          "spans": ["S04", "S05"]
        },
        {
          "fact": "戊承诺乙不履行到期B债务即无条件清偿、无须先向乙追索；期间写为本息还清为止。B原到期日2023-01-12，展期至2023-06-30未经戊书面同意。甲在2023-07-05起诉戊，未送达且戊不知悉请求即于2023-07-09撤诉，另行催告发生于2023-07-18。",
          "spans": ["S06"]
        },
        {
          "fact": "C于2019-02-07实际交付224510.00元并成立，到期日2022-12-15，约定年利率及逾期利率均为23.50%。2022年另签保证不构成借款更新。题设各次受理时一年期LPR均为3.55%；甲明确请求对2020-08-19以前利息适用当时司法解释。",
          "spans": ["S07"]
        },
        {
          "fact": "C费用1680.00元于2019-04-17发生并到期。原合同约定付款依次清偿费用、依法可请求利息、本金；双方仅对T-02改约为本金优先。其他记录中的还本金备注仅为乙单方记载。利息按未偿本金及实际日数/365单利计算，付款日不再对当日偿还本金计息。",
          "spans": ["S07", "S09"]
        },
        {
          "fact": "T-01至T-07为七笔实际到账的C付款；截图及收据中的T-01与主表同号。X-01仅提交指令，银行未执行、未入账。乙关于操作已完成的表述是单方主张。",
          "spans": ["S08", "S11"]
        },
        {
          "fact": "己于2022-02-07承诺乙不能履行、无力偿还时才代偿，未约定保证期间。甲于2023-06-08起诉乙，撤诉后于2023-06-14再次起诉；截至截日未审判、无执行款。己仅确认收到催告书，未作新保证或放弃先诉抗辩；题设明确不存在民法典第687条例外。",
          "spans": ["S10"]
        },
        {
          "fact": "SP-01于2023-08-01实际到账25000.00元，双方限定只用于B/C但未在二者之间指定或约定顺序；B/C除各自保证外没有其他担保。最终核对付款后的余额，不计截日利息；诉请不包括保证合同无效后的过错赔偿，分项取分后相加。",
          "spans": ["S12", "S13"]
        }
      ],
      "support_spans": [
        {
          "kind": "material",
          "span_ids": ["S01", "S02"],
          "key_excerpt": "套取的信贷资金转给乙；如A被认定无效，双方同意在清算中全部作为已返还财产冲抵。"
        },
        {
          "kind": "material",
          "span_ids": ["S03", "S04", "S05"],
          "key_excerpt": "实际收到184070.00元，当日起息，合同也于该日成立；各归档日的新增银行转账均为0元；双方不另成立债务更新合同。"
        },
        {
          "kind": "material",
          "span_ids": ["S06"],
          "key_excerpt": "无须甲先向乙追索；戊未书面同意展期；截至撤诉日未向戊送达，戊此前也未获知起诉和给付请求。"
        },
        {
          "kind": "material",
          "span_ids": ["S07", "S09"],
          "key_excerpt": "2022年保证文件不构成另起借款合同或债务更新；甲明确请求按照合同成立至2020-08-19当时的司法解释计算该段利息；补充协议仅适用于T-02。"
        },
        {
          "kind": "material",
          "span_ids": ["S08", "S11"],
          "key_excerpt": "两份记录的银行交易号均与S08首行相同；X-01未执行，已撤销付款指令，未向甲账户记入该金额。"
        },
        {
          "kind": "material",
          "span_ids": ["S10"],
          "key_excerpt": "不能履行C债务、无力偿还时，己才代为向甲清偿；2023-06-14重新对乙起诉；收到，不确认付款义务。"
        },
        {
          "kind": "material",
          "span_ids": ["S12", "S13"],
          "key_excerpt": "该款只用于清偿B、C两笔借款，不用于A返还债务；B、C均无各自保证合同以外的抵押、质押或其他担保；各输出分项最终取分后再相加形成总额。"
        },
        {
          "kind": "rule",
          "source_id": "lending-2020-12",
          "provisions": ["13", "25", "26", "27", "28", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "supports": "套取贷款转贷的效力、实际本金、利率保护、结息及整体上限、逾期利息、旧借款利息过渡。"
        },
        {
          "kind": "rule",
          "source_id": "lending-2015",
          "provisions": ["26"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html",
          "supports": "C在过渡规则指定旧法期间内适用的24%年利率保护标准。"
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["157", "560", "561", "670", "679", "682", "687", "688", "691", "692", "693", "695"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "supports": "无效返还、数项债务与债务内部抵充、实际交付、保证从属性、保证方式及期间、未获保证人书面同意的展期效果。"
        },
        {
          "kind": "rule",
          "source_id": "guarantee-2020",
          "provisions": ["25", "31", "32", "34"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html",
          "supports": "依原始条款识别保证类型、区分撤诉效果、解释还清为止条款及仅在催告书签收的法律意义。"
        }
      ],
      "dependencies": {
        "nodes": [
          {
            "id": "A_BALANCE",
            "subject": "A效力及返还范围",
            "supported_state": "依题设来源事实和适用版本，A落入套取金融机构贷款转贷的无效情形；返还基数为实际交付财产，按条件式清算协议扣除已返还款。同号收据不形成第二次交付。",
            "evidence": ["S01", "S02"],
            "authorities": [
              "lending-2020-12:13",
              "civil-code-2020:157"
            ],
            "output": "A剩余财产返还额；不是约定本息请求。"
          },
          {
            "id": "A_GUARANTEE",
            "subject": "丁的合同保证责任",
            "supported_state": "主合同无效且题设排除其他例外，丁的从属保证合同无效；不能据该保证合同要求立即清偿。过错赔偿不在本单元请求范围内。",
            "evidence": ["S01", "S12"],
            "authorities": ["civil-code-2020:682"],
            "output": "保证无效状态及即时保证给付请求的处理范围。"
          },
          {
            "id": "B_BALANCE",
            "subject": "B结息及SP-01前可保护余额",
            "supported_state": "以184070.00元实际交付额为初始本金，不能直接采用原票面或归档纸面金额。13.20%约定年利率低于题设LPR四倍14.80%；仍须重建各期合法结息金额，并与第27条整体上限比较，不能直接把整体上限当成应付金额。",
            "evidence": ["S03", "S04", "S05", "S06", "S12", "S13"],
            "authorities": [
              "civil-code-2020:670",
              "civil-code-2020:679",
              "lending-2020-12:25",
              "lending-2020-12:26",
              "lending-2020-12:27",
              "lending-2020-12:28"
            ],
            "output": "逐期合法结息、整体上限比较及展期后逾期区间共同限定的付款前本息余额。"
          },
          {
            "id": "B_GUARANTEE",
            "subject": "戊的保证类型及期间行权",
            "supported_state": "原始措辞支持连带责任保证。还清为止属于期间约定不明；未经戊书面同意的展期不改变保证期间，按原到期日起六个月核对至2023-07-12。期间内起诉后未送达即撤诉，亦无其他期间内请求；2023-07-18催告不能补足，戊保证责任消灭。",
            "evidence": ["S06"],
            "authorities": [
              "civil-code-2020:688",
              "civil-code-2020:692",
              "civil-code-2020:693",
              "civil-code-2020:695",
              "guarantee-2020:25",
              "guarantee-2020:31",
              "guarantee-2020:32",
              "guarantee-2020:34"
            ],
            "output": "SP-01抵充时B缺乏保证；戊不承担题设所请求的即时保证给付责任。"
          },
          {
            "id": "C_BALANCE",
            "subject": "C分时利率、付款识别及余额",
            "supported_state": "C借款成立于2019年，不能以2022年保证成立替换借款成立时间。按所给过渡规则，2020-08-19以前适用23.50%约定利率，2020-08-20起保护标准为题设受理时LPR四倍14.20%。T-01只计一次，X-01不计付款；T-02依双方补充协议先抵本金，其余付款依原合同先费用、后合法利息、再本金。",
            "evidence": ["S07", "S08", "S09", "S11", "S12"],
            "authorities": [
              "lending-2015:26",
              "lending-2020-12:25",
              "lending-2020-12:28",
              "lending-2020-12:31",
              "civil-code-2020:561"
            ],
            "output": "按付款日及2020-08-20规范切点分段重建的未偿本金、合法利息和费用。",
            "temporal_boundary": "2021年前付款的顺序以S09明确的原合同及补充协议为依据，不追溯套用民法典第561条。"
          },
          {
            "id": "C_GUARANTEE",
            "subject": "己的保证存续与先诉抗辩",
            "supported_state": "原始措辞支持一般保证；未约定期间，按C到期日起六个月核对至2023-06-15。首次撤诉后于2023-06-14对乙再诉，仍在期间内，保证责任不因首次撤诉消灭。尚未审判执行且无先诉抗辩例外，己可拒绝立即承担保证责任；仅签收不构成新保证或放弃抗辩。",
            "evidence": ["S07", "S10"],
            "authorities": [
              "civil-code-2020:687",
              "civil-code-2020:691",
              "civil-code-2020:692",
              "civil-code-2020:693",
              "guarantee-2020:25",
              "guarantee-2020:31",
              "guarantee-2020:34"
            ],
            "output": "C保证仍存续，但即时给付条件未满足；不能将先诉抗辩等同于无担保。"
          },
          {
            "id": "SP_ALLOCATION",
            "subject": "SP-01在B/C之间的抵充",
            "supported_state": "双方先将候选债务限定为B/C。截日二者均已到期；B保证责任消灭而C仍有一般保证，依第560条应优先清偿缺乏担保的B。B付款前余额足以吸收25000.00元时，该款全部抵B，不再进入负担轻重或到期先后的后顺位比较。",
            "evidence": ["S06", "S07", "S10", "S13"],
            "authorities": ["civil-code-2020:560"],
            "output": "SP-01归属B；A不受该付款影响，C不因该笔付款减少。"
          },
          {
            "id": "FINAL_BALANCES",
            "subject": "付款后剩余分项及合计",
            "supported_state": "分别汇总A返还余额、B抵充后的可保护本息余额、C未偿本金及合法利息和费用；不重复累计原票面、重复凭证、失败指令或保证债务。截日不计息，按题设输出分项最终取分后相加。",
            "evidence": ["S02", "S04", "S07", "S11", "S12", "S13"],
            "authorities": [],
            "output": "待十进制定点复算的分项及总额，不在P1生成精确金额参考。"
          },
          {
            "id": "IMMEDIATE_GUARANTEE_RELIEF",
            "subject": "三名保证人的即时给付请求",
            "supported_state": "须分别保留丁的保证无效、戊的保证责任消灭、己的保证存续但享有先诉抗辩三种状态，不能用同一否定标签替代其不同依据。",
            "evidence": ["S01", "S06", "S10", "S12"],
            "authorities": [
              "civil-code-2020:682",
              "civil-code-2020:687",
              "civil-code-2020:693",
              "guarantee-2020:34"
            ],
            "output": "在题设截至日及请求范围内，三项立即按保证合同付款的请求均缺乏相应支持，但理由不同。"
          }
        ],
        "edges": [
          {
            "from": "A_BALANCE",
            "to": "A_GUARANTEE",
            "relationship": "主合同效力决定从属保证效力。"
          },
          {
            "from": "B_GUARANTEE",
            "to": "SP_ALLOCATION",
            "relationship": "戊保证责任是否存续决定B的担保比较状态。"
          },
          {
            "from": "C_GUARANTEE",
            "to": "SP_ALLOCATION",
            "relationship": "己的先诉抗辩不消灭保证，影响B/C担保优先级比较。"
          },
          {
            "from": "B_BALANCE",
            "to": "SP_ALLOCATION",
            "relationship": "核对B是否仍未清偿以及能否吸收全部SP-01。"
          },
          {
            "from": "C_BALANCE",
            "to": "SP_ALLOCATION",
            "relationship": "核对C仍为待清偿的到期候选债务。"
          },
          {
            "from": "A_BALANCE",
            "to": "FINAL_BALANCES",
            "relationship": "提供独立于SP-01的A返还余额。"
          },
          {
            "from": "B_BALANCE",
            "to": "FINAL_BALANCES",
            "relationship": "提供B付款前合法本息基数。"
          },
          {
            "from": "C_BALANCE",
            "to": "FINAL_BALANCES",
            "relationship": "提供C分时付款后的本金、合法利息和费用。"
          },
          {
            "from": "SP_ALLOCATION",
            "to": "FINAL_BALANCES",
            "relationship": "确定25000.00元应从哪一债务分项扣除。"
          },
          {
            "from": "A_GUARANTEE",
            "to": "IMMEDIATE_GUARANTEE_RELIEF",
            "relationship": "区分保证无效与其他拒绝给付原因。"
          },
          {
            "from": "B_GUARANTEE",
            "to": "IMMEDIATE_GUARANTEE_RELIEF",
            "relationship": "提供期间内未有效行权导致责任消灭的状态。"
          },
          {
            "from": "C_GUARANTEE",
            "to": "IMMEDIATE_GUARANTEE_RELIEF",
            "relationship": "提供保证仍存续但尚不能立即请求给付的状态。"
          }
        ]
      },
      "answerability": {
        "status": "answerable_on_stipulated_facts",
        "basis": "主要法律分支、付款身份、适用时点、金额归属和计算约定均有题设及所给规范摘录支持。",
        "court_holding": null,
        "legal_states": "仅为虚构题设与给定规范支持的状态，不是法院实际认定。",
        "amounts": "具备建立可复算参考的必要输入；本阶段未完成逐日十进制计算或独立复算。",
        "release_status": "仅完成P1依赖结构提取，不构成最终训练准入。"
      }
    }
  ],
  "rejected_units": [
    {
      "issue": "提取原案法院实际裁判结论、裁判理由或裁判金额",
      "reason": "当前材料显著标为虚构衍生情景，没有提供可供提取的实际法院判断，不能继承研究动机原案的标签。"
    },
    {
      "issue": "确定保证合同无效后的具体过错赔偿",
      "reason": "S12明确排除该项请求，且材料不足以支持具体过错比例及赔偿金额。"
    },
    {
      "issue": "将乙单方备注或提交付款指令直接认定为有效改约或已清偿",
      "reason": "S09未记载甲同意其他本金优先安排；S11明确银行未执行X-01，不能以单方表述替代约定或到账事实。"
    }
  ],
  "limitations": [
    "全部案件事实仅作为显著虚构题设使用；来源元数据中的历史机制、修改假设和研究者参考不是新增事实或答案依据。",
    "本次未访问外部网页或重新校验哈希、定位及版本；规范依据对齐限于用户提供的摘录和公开来源链接。两项LPR均为题设假定，不是现实报价核验结果。",
    "规范来源包含不同时期条文。A/B的2022年关系不能套用2015年转贷无效要件；C的2019年借款与2022年保证必须分别识别成立时间。",
    "正文序言中的虚构标识、事实认可范围、主体资格、截日和例外排除属于必要边界，但未列入S01至S13的独立编号。后续学生投影须完整保留并补充中性定位，不得静默删除。",
    "SP-01的担保比较影响B/C分项余额，但在两笔余额均足以承受同额清偿时，仅观察总债务减少25000.00元不能检验抵充归属是否正确；后续审核须保留分项和保证状态。",
    "本阶段未生成题面、未接收种子、未开展盲答或经验难度测量；依赖节点数量不等于实测难度。"
  ]
}
